def test_speculative_submit_untracked_returns_cache_bypassed_response(
    run_cache: RunCache, query_cache_client: Mock, mocker: MockerFixture
) -> None:
    """An untracked-execute verdict awaits the prefetch and records real timestamps."""
    node = create_model_node({"materialized": "table"})
    setup_submit_sql_mocks(run_cache, mocker)
    run_cache._adapter_ext.get_available_last_modified_epochs = mocker.Mock(
        return_value={"table1": None, "test_table": None}
    )
    mocker.patch.object(run_cache, "_is_prefetch_ready", return_value=False)
    await_mock = mocker.patch.object(run_cache, "_await_prefetch_last_modified")

    query_cache_client.submit_sql_speculative = mocker.Mock(
        return_value=sql_service_models.ReadyToExecuteUntrackedResponse()
    )
    query_cache_client.submit_sql = mocker.Mock()

    result = run_cache._submit_sql_request(node)

    assert isinstance(result, CacheBypassedResponse)
    assert result.node is node
    await_mock.assert_called_once()
    query_cache_client.submit_sql.assert_not_called()
    run_cache._adapter_ext.get_last_modified_epoch.assert_called_once()
    epochs_by_name = {info.name: info.last_modified_epoch for info in result.request.tables}
    assert epochs_by_name == {"table1": 1234567890, "test_table": 9876543210}

